/**
 * A tiny bundled speech clip used to sanity-check an accelerated (WebGPU or
 * WebNN) ASR pipeline right after it builds (see worker.ts handleInit's
 * post-build output probe): a GPU can pass its runtime handshake and build
 * the inference graph fine and *still* emit degenerate output ("!!!!"
 * repeated, verified in production on real hardware) on some devices — only
 * running a known-good probe transcript through the pipeline catches that.
 *
 * Extracted from apps/site/tests/fixtures/jfk16k.wav (16 kHz mono PCM, the
 * classic "...ask not what your country can do for you..." speech sample
 * already used by the site's e2e fixtures): a 2.0 s slice starting at 0.30 s
 * — the recording's first clean, uninterrupted stretch of speech ("And so,
 * my fellow Americans", per ffmpeg silencedetect) — trimmed with:
 *
 *   ffmpeg -i jfk16k.wav -ss 0.30 -t 2.0 -ar 16000 -ac 1 -c:a pcm_s16le clip.wav
 *
 * Embedded below as base64-encoded little-endian int16 PCM (not Float32) to
 * keep this module small — roughly half the size of a Float32 embed for the
 * same audio. Decoded to a 16 kHz mono Float32Array in [-1, 1] at runtime by
 * `getValidationClip`. No DOM, no AudioContext, no network: worker-safe per
 * CLAUDE.md rule 2, and framework-free per rule 3 (pure decode, no globals
 * beyond `atob`, which every worker/browser/Node >= 16 runtime provides).
 */

export const VALIDATION_CLIP_SAMPLE_RATE = 16_000;

// 2.0 s @ 16 kHz mono, base64 little-endian int16 PCM (32,000 samples).
const VALIDATION_CLIP_BASE64 =
  '';

let cached: Float32Array | null = null;

/**
 * Decodes (and memoizes) the bundled validation clip as 16 kHz mono PCM
 * samples in [-1, 1], ready to hand straight to an ASR pipeline.
 */
export function getValidationClip(): Float32Array {
  if (cached) return cached;
  const binary = atob(VALIDATION_CLIP_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const int16 = new Int16Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 2);
  const float32 = new Float32Array(int16.length);
  for (let i = 0; i < int16.length; i++) {
    const sample = int16[i];
    float32[i] = (sample ?? 0) / 32768;
  }
  cached = float32;
  return float32;
}
